CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE TABLE IF NOT EXISTS "user" (id text PRIMARY KEY, name text NOT NULL, email text UNIQUE NOT NULL, "emailVerified" boolean NOT NULL DEFAULT false, image text, "createdAt" timestamptz NOT NULL DEFAULT now(), "updatedAt" timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS session (id text PRIMARY KEY,"expiresAt" timestamptz NOT NULL,token text UNIQUE NOT NULL,"createdAt" timestamptz NOT NULL DEFAULT now(),"updatedAt" timestamptz NOT NULL DEFAULT now(),"ipAddress" text,"userAgent" text,"userId" text NOT NULL REFERENCES "user"(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS account (id text PRIMARY KEY,"accountId" text NOT NULL,"providerId" text NOT NULL,"userId" text NOT NULL REFERENCES "user"(id) ON DELETE CASCADE,"accessToken" text,"refreshToken" text,"idToken" text,"accessTokenExpiresAt" timestamptz,"refreshTokenExpiresAt" timestamptz,scope text,password text,"createdAt" timestamptz NOT NULL DEFAULT now(),"updatedAt" timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS verification (id text PRIMARY KEY,identifier text NOT NULL,value text NOT NULL,"expiresAt" timestamptz NOT NULL,"createdAt" timestamptz DEFAULT now(),"updatedAt" timestamptz DEFAULT now());
CREATE TABLE memberships(user_id text NOT NULL REFERENCES "user"(id),workspace_id text NOT NULL,role text NOT NULL CHECK(role IN ('owner','operator','seller','reconciler','analyst','viewer')),active boolean NOT NULL DEFAULT true,PRIMARY KEY(user_id,workspace_id));
CREATE TABLE records(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),workspace_id text NOT NULL,environment text NOT NULL CHECK(environment IN ('SIMULATION','REAL')),kind text NOT NULL,version integer NOT NULL DEFAULT 1 CHECK(version>0),body jsonb NOT NULL CHECK(jsonb_typeof(body)='object'),created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),UNIQUE(workspace_id,kind,id));
CREATE INDEX records_lookup ON records(workspace_id,environment,kind,created_at DESC);
CREATE INDEX records_body ON records USING gin(body jsonb_path_ops);
CREATE TABLE record_versions(record_id uuid NOT NULL REFERENCES records(id),workspace_id text NOT NULL,environment text NOT NULL,kind text NOT NULL,version integer NOT NULL,body jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(record_id,version));
CREATE FUNCTION snapshot_record() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN INSERT INTO record_versions(record_id,workspace_id,environment,kind,version,body) VALUES(NEW.id,NEW.workspace_id,NEW.environment,NEW.kind,NEW.version,NEW.body); RETURN NEW; END $$;
CREATE TRIGGER snapshot_record AFTER INSERT OR UPDATE ON records FOR EACH ROW EXECUTE FUNCTION snapshot_record();
CREATE FUNCTION guard_record() RETURNS trigger LANGUAGE plpgsql AS $$
DECLARE key text; target text; expected text; ref jsonb;
BEGIN
 IF TG_OP='UPDATE' THEN
  IF OLD.kind IN ('offer','bank_profile','receipt_policy') OR (OLD.kind='workflow' AND OLD.body->>'status'='PUBLISHED') THEN RAISE EXCEPTION 'IMMUTABLE_VERSION'; END IF;
  IF NEW.workspace_id<>OLD.workspace_id OR NEW.environment<>OLD.environment OR NEW.kind<>OLD.kind OR NEW.version<>OLD.version+1 THEN RAISE EXCEPTION 'VERSION_CONFLICT'; END IF;
 END IF;
 FOR key,target IN SELECT * FROM jsonb_each_text(NEW.body) LOOP
 expected:=CASE key WHEN 'product_id' THEN 'product' WHEN 'offer_version_id' THEN 'offer' WHEN 'workflow_version_id' THEN 'workflow' WHEN 'agent_version_id' THEN 'agent' WHEN 'payment_profile_version_id' THEN 'bank_profile' WHEN 'receipt_policy_version_id' THEN 'receipt_policy' WHEN 'campaign_id' THEN 'acquisition_campaign' WHEN 'ad_set_id' THEN 'ad_set' WHEN 'ad_id' THEN 'ad' WHEN 'account_id' THEN 'channel_account' WHEN 'contact_id' THEN 'contact' WHEN 'conversation_id' THEN 'conversation' WHEN 'order_id' THEN 'order' WHEN 'asset_id' THEN 'asset' ELSE NULL END;
 IF expected IS NOT NULL AND target IS NOT NULL AND NOT EXISTS(SELECT 1 FROM records r WHERE r.id::text=target AND r.workspace_id=NEW.workspace_id AND r.environment=NEW.environment AND r.kind=expected) THEN RAISE EXCEPTION 'INVALID_SCOPED_REFERENCE: %',key; END IF;
 END LOOP;
 IF NEW.body ? 'fulfillment' THEN FOR ref IN SELECT * FROM jsonb_array_elements(NEW.body->'fulfillment') LOOP IF NOT EXISTS(SELECT 1 FROM records r WHERE r.id::text=ref->>'asset_id' AND r.workspace_id=NEW.workspace_id AND r.environment=NEW.environment AND r.kind='asset') THEN RAISE EXCEPTION 'INVALID_ASSET_REFERENCE'; END IF; END LOOP; END IF;
 RETURN NEW;
END $$;
CREATE TRIGGER guard_record BEFORE INSERT OR UPDATE ON records FOR EACH ROW EXECUTE FUNCTION guard_record();
CREATE FUNCTION immutable_row() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'IMMUTABLE_EVIDENCE'; END $$;
CREATE TRIGGER immutable_versions BEFORE UPDATE OR DELETE ON record_versions FOR EACH ROW EXECUTE FUNCTION immutable_row();
CREATE TABLE commands(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),workspace_id text NOT NULL,environment text NOT NULL CHECK(environment IN ('SIMULATION','REAL')),kind text NOT NULL,resource_id text NOT NULL,actor_id text NOT NULL,payload jsonb NOT NULL DEFAULT '{}',status text NOT NULL DEFAULT 'PENDING' CHECK(status IN ('PENDING','APPLIED','FAILED')),result jsonb NOT NULL DEFAULT '{}',idempotency_key text NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),UNIQUE(workspace_id,actor_id,idempotency_key));
CREATE INDEX commands_pending ON commands(created_at) WHERE status='PENDING';
CREATE TABLE manual_controls(workspace_id text NOT NULL,scope_type text NOT NULL CHECK(scope_type IN ('workspace','channel_account','conversation','contact','workflow')),scope_id text NOT NULL,paused boolean NOT NULL DEFAULT false,takeover boolean NOT NULL DEFAULT false,suppressed boolean NOT NULL DEFAULT false,version integer NOT NULL DEFAULT 1,reason text NOT NULL,actor_id text NOT NULL,updated_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(workspace_id,scope_type,scope_id));
CREATE TABLE domain_events(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),workspace_id text NOT NULL,environment text NOT NULL CHECK(environment IN ('SIMULATION','REAL')),event_type text NOT NULL,schema_version integer NOT NULL DEFAULT 1,aggregate_id text NOT NULL,correlation_id text NOT NULL,causation_id text,actor jsonb NOT NULL DEFAULT '{}',payload jsonb NOT NULL DEFAULT '{}',occurred_at timestamptz NOT NULL DEFAULT now(),recorded_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX domain_events_aggregate ON domain_events(workspace_id,aggregate_id,recorded_at);
CREATE TRIGGER immutable_events BEFORE UPDATE OR DELETE ON domain_events FOR EACH ROW EXECUTE FUNCTION immutable_row();
CREATE TABLE inbound_envelopes(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),workspace_id text NOT NULL,environment text NOT NULL CHECK(environment IN ('SIMULATION','REAL')),account_id text NOT NULL,provider text NOT NULL,provider_event_id text NOT NULL,payload_ciphertext text NOT NULL,metadata jsonb NOT NULL DEFAULT '{}',occurred_at timestamptz NOT NULL DEFAULT now(),received_at timestamptz NOT NULL DEFAULT now(),processed_at timestamptz,status text NOT NULL DEFAULT 'PENDING',error text,UNIQUE(workspace_id,account_id,provider,provider_event_id));
CREATE INDEX inbound_pending ON inbound_envelopes(received_at) WHERE status='PENDING';
CREATE TABLE operation_authorizations(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),workspace_id text NOT NULL,environment text NOT NULL CHECK(environment IN ('SIMULATION','REAL')),actor_id text NOT NULL,scope jsonb NOT NULL,config_hash text NOT NULL,expires_at timestamptz NOT NULL,revoked_at timestamptz,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE outbox(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),workspace_id text NOT NULL,environment text NOT NULL CHECK(environment IN ('SIMULATION','REAL')),account_id text NOT NULL,conversation_id text NOT NULL,contact_id text NOT NULL,logical_key text NOT NULL,kind text NOT NULL DEFAULT 'message',payload jsonb NOT NULL,status text NOT NULL DEFAULT 'READY' CHECK(status IN ('READY','SENDING','SENT','DELIVERED','READ','FAILED','UNKNOWN','CANCELLED','BLOCKED')),predecessor_id uuid REFERENCES outbox(id),config_hash text NOT NULL,approval_hash text,authorization_id uuid REFERENCES operation_authorizations(id),control_version integer NOT NULL DEFAULT 0,not_before timestamptz NOT NULL DEFAULT now(),expires_at timestamptz NOT NULL DEFAULT now()+interval '24 hours',claim_id text,claimed_at timestamptz,provider_message_id text,result jsonb NOT NULL DEFAULT '{}',attempts integer NOT NULL DEFAULT 0,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),UNIQUE(workspace_id,logical_key));
CREATE INDEX outbox_ready ON outbox(account_id,not_before) WHERE status='READY';
CREATE TABLE effect_attempts(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),effect_id uuid NOT NULL REFERENCES outbox(id),claim_id text NOT NULL,status text NOT NULL,result jsonb NOT NULL DEFAULT '{}',started_at timestamptz NOT NULL DEFAULT now(),finished_at timestamptz);
CREATE TABLE timers(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),workspace_id text NOT NULL,environment text NOT NULL,conversation_id text NOT NULL,kind text NOT NULL,payload jsonb NOT NULL DEFAULT '{}',due_at timestamptz NOT NULL,status text NOT NULL DEFAULT 'PENDING' CHECK(status IN ('PENDING','FIRED','CANCELLED')),logical_key text NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(workspace_id,logical_key));
CREATE INDEX timers_pending ON timers(due_at) WHERE status='PENDING';
CREATE TABLE session_ownership(account_id text PRIMARY KEY,workspace_id text NOT NULL,owner_id text NOT NULL,generation integer NOT NULL DEFAULT 1,frozen boolean NOT NULL DEFAULT true,lease_expires_at timestamptz NOT NULL,isolation_evidence text,updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE idempotency(workspace_id text NOT NULL,actor_id text NOT NULL,operation text NOT NULL,key text NOT NULL,request_hash text NOT NULL,response jsonb NOT NULL,status_code integer NOT NULL,PRIMARY KEY(workspace_id,actor_id,operation,key));
CREATE TABLE service_tokens(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),workspace_id text NOT NULL,actor_id text NOT NULL,name text NOT NULL,token_hash text NOT NULL UNIQUE,scopes jsonb NOT NULL,expires_at timestamptz NOT NULL,revoked_at timestamptz,created_at timestamptz NOT NULL DEFAULT now());
